import { SingleCoinImage } from '@cetus/ui-kit'
import { Box, CenterProps } from '@chakra-ui/react'

interface TokenAvatarProps {
  size?: string
  src: string
  coin_type?: string
  variant?: 'border' | ''
  style?: CenterProps
}

function TokenAvatar({ coin_type, size = '38px', src, variant, style = {} }: TokenAvatarProps) {
  return (
    <Box w={size} h={size} minW={size} minH={size} maxW={size} maxH={size} borderRadius="50%">
      <SingleCoinImage variant={variant} imageUrl={src} w={size} h={size} borderRadius="50%" coinType={coin_type} p="4px" imgBoxStyle={style} />
    </Box>
  )
}

export default TokenAvatar
